#pragma once
#include <string>
#include <unordered_map>
#include <vector>

/**
 * L1: File integrity verification via env.lock.
 *
 * env.lock is a JSON manifest generated by tools/gen_envlock.py:
 * {
 *   "fg_version": "2024.1.7",
 *   "fg_binaries": {"fgfs.exe": "<sha256>", ...},
 *   "aircraft": {"c172p": {"set_xml": "...", "key_files": {...}}, ...},
 *   "scenery": {"apt_dat": {...}, "terrain": {...}}
 * }
 *
 * Verification computes SHA256 of each file and compares against manifest.
 */

class L1_Integrity {
public:
    struct CheckResult {
        bool passed;
        std::string layer;   // "L1"
        std::string detail;
        std::vector<std::string> issues;
    };

    explicit L1_Integrity(const std::string& lock_file_path);
    CheckResult verify(const std::string& fg_root,
                       const std::string& fg_bin_dir,
                       const std::string& scenery_dir) const;

private:
    struct LockData {
        std::string fg_version;
        std::unordered_map<std::string, std::string> fg_binaries;
        std::unordered_map<std::string, std::unordered_map<std::string, std::string>> aircraft;
        std::unordered_map<std::string, std::unordered_map<std::string, std::string>> scenery;
        bool parsed;
    };

    std::string compute_sha256(const std::string& filepath) const;
    std::optional<LockData> load_lock(const std::string& path) const;

    LockData lock_data_;
};
